css:
@keyframes auroraFluidMotion {
  0% {
    background-position: 20% 15%, 80% 30%, 50% 65%, 0 0;
  }
  33% {
    background-position: 60% 35%, 30% 15%, 80% 45%, 0 0;
  }
  66% {
    background-position: 80% 15%, 70% 45%, 20% 35%, 0 0;
  }
  100% {
    background-position: 20% 15%, 80% 30%, 50% 65%, 0 0;
  }
}
[data-workspace-area="conversation"] {
  background-color: #050b14 !important;
  background-image: 
    radial-gradient(ellipse at 25% 20%, rgba(45, 212, 191, 0.32) 0%, transparent 55%),
    radial-gradient(ellipse at 75% 30%, rgba(56, 189, 248, 0.28) 0%, transparent 50%),
    radial-gradient(ellipse at 50% 70%, rgba(168, 85, 247, 0.24) 0%, transparent 60%),
    url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A//www.w3.org/2000/svg%27%20width%3D%27200%27%20height%3D%27200%27%20viewBox%3D%270%200%20200%20200%27%3E%0A%3Ccircle%20cx%3D%2725%27%20cy%3D%2735%27%20r%3D%271.2%27%20fill%3D%27%2523e0f2fe%27%20opacity%3D%270.75%27/%3E%0A%3Ccircle%20cx%3D%2780%27%20cy%3D%2720%27%20r%3D%271.8%27%20fill%3D%27%2523ffffff%27%20opacity%3D%270.9%27/%3E%0A%3Ccircle%20cx%3D%27140%27%20cy%3D%2750%27%20r%3D%271%27%20fill%3D%27%2523bae6fd%27%20opacity%3D%270.6%27/%3E%0A%3Ccircle%20cx%3D%27185%27%20cy%3D%2725%27%20r%3D%271.5%27%20fill%3D%27%2523e0f2fe%27%20opacity%3D%270.8%27/%3E%0A%3Ccircle%20cx%3D%2745%27%20cy%3D%27110%27%20r%3D%271%27%20fill%3D%27%2523ffffff%27%20opacity%3D%270.65%27/%3E%0A%3Ccircle%20cx%3D%27110%27%20cy%3D%2790%27%20r%3D%271.6%27%20fill%3D%27%2523e0f2fe%27%20opacity%3D%270.85%27/%3E%0A%3Ccircle%20cx%3D%27165%27%20cy%3D%27130%27%20r%3D%271.2%27%20fill%3D%27%2523bae6fd%27%20opacity%3D%270.7%27/%3E%0A%3Ccircle%20cx%3D%2730%27%20cy%3D%27175%27%20r%3D%271.5%27%20fill%3D%27%2523ffffff%27%20opacity%3D%270.8%27/%3E%0A%3Ccircle%20cx%3D%2795%27%20cy%3D%27160%27%20r%3D%271%27%20fill%3D%27%2523e0f2fe%27%20opacity%3D%270.65%27/%3E%0A%3Ccircle%20cx%3D%27150%27%20cy%3D%27180%27%20r%3D%272%27%20fill%3D%27%2523ffffff%27%20opacity%3D%270.95%27/%3E%0A%3C/svg%3E") !important;
  background-repeat: no-repeat, no-repeat, no-repeat, repeat !important;
  background-size: 150% 150%, 140% 140%, 160% 160%, 200px 200px !important;
  animation: auroraFluidMotion 22s ease-in-out infinite !important;
}
.chat-markdown-codeblock {
  backdrop-filter: blur(16px) saturate(160%) !important;
  background: rgba(10, 22, 38, 0.74) !important;
  border: 1px solid rgba(45, 212, 191, 0.22) !important;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4) !important;
}
[data-chat-header] {
  backdrop-filter: blur(14px) !important;
  background: rgba(6, 13, 23, 0.8) !important;
  border-bottom: 1px solid rgba(45, 212, 191, 0.16) !important;
}
